def min_blows_to_defeat_gorynich(t, queries):
    from functools import lru_cache

    def solve(n, x, blows):
        @lru_cache(None)
        def dp(curX):
            if curX <= 0:
                return 0
            min_blows = float('inf')
            for d, h in blows:
                if d > curX:
                    continue
                new_heads = curX - d + h
                result = dp(new_heads)
                if result != -1:
                    min_blows = min(min_blows, 1 + result)
            return min_blows if min_blows != float('inf') else -1

        return dp(x)

    results = []
    for i in range(t):
        n, x = queries[i][0]
        blows = queries[i][1]
        results.append(solve(n, x, blows))

    return results

# Example usage:
t = 3
queries = [
    ((3, 10), [(6, 3), (8, 2), (1, 4)]),
    ((4, 10), [(4, 1), (3, 2), (2, 6), (1, 100)]),
    ((11, 10), [(14, 100)])
]

results = min_blows_to_defeat_gorynich(t, queries)
for result in results:
    print(result)
